def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, 18.0))

    bob_prev_bid = None
    cindy_alive = False
    pressure_bids = []
    weak_count = 0

    for agent_id, opp in opponents_status.items():
        if not opp.get('alive'):
            continue
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            pressure_bids.append(float(bid))
        if agent_id == 'Bob' and bid is not None:
            bob_prev_bid = float(bid)
        if agent_id == 'Cindy':
            cindy_alive = True
        if opp.get('budget', 0) < 80 or opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            weak_count += 1

    tight_supply = supply <= 17
    loose_supply = supply >= 22
    urgent = hp <= 3 or no_water >= 1
    critical = hp <= 2 or no_water >= 2

    if critical:
        target = 148.0 if cindy_alive else 110.0
    elif urgent:
        if bob_prev_bid is not None:
            target = max(92.0, min(120.0, bob_prev_bid + 4.0))
        else:
            target = 96.0
    else:
        if tight_supply:
            if bob_prev_bid is not None:
                target = max(72.0, min(112.0, bob_prev_bid + 2.0))
            else:
                target = 78.0
        elif loose_supply:
            target = 18.0 if weak_count >= 2 else 26.0
        else:
            if pressure_bids:
                prev_max = max(pressure_bids)
                if prev_max >= 140.0:
                    target = 24.0
                elif prev_max >= 100.0:
                    target = 58.0
                else:
                    target = max(32.0, prev_max + 2.0)
            else:
                target = 42.0

    reserve_floor = 0.0
    if hp >= 5 and no_water == 0:
        reserve_floor = 35.0
    elif hp >= 3:
        reserve_floor = 20.0

    affordable = max(0.0, budget - reserve_floor)
    if urgent or critical:
        affordable = budget

    bid = min(target, affordable)

    if bid < 0:
        bid = 0.0
    if urgent and bid < 35.0 and budget >= 35.0:
        bid = 35.0

    return float(min(bid, budget))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opps = [o for o in opponents_status.values() if o.get('alive')]
    if not alive_opps:
        return max(0.0, min(float(my_status['budget']), DAILY_SALARY * 0.4))

    # Use only yesterday previous_trace to infer pressure
    yesterday_bids = []
    yesterday_hp_after = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(float(prev['bid']))
            yesterday_hp_after.append(prev.get('hp_after', None))

    my_budget = float(my_status['budget'])
    my_hp = float(my_status['hp'])

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    # Cindy-like behavior: survival implies she likely bid aggressively.
    # If someone bid very high yesterday, assume they will contest again.
    pressure = 0.0
    if highest_prev_bid >= 120.0:
        pressure = 1.0
    elif highest_prev_bid >= 60.0:
        pressure = 0.7
    elif highest_prev_bid >= 20.0:
        pressure = 0.4
    else:
        pressure = 0.2

    # Supply-based urgency: with lower supply, water is scarcer.
    # Map supply to a factor in [0.3, 1.0]
    if supply <= MIN_SUPPLY:
        supply_factor = 1.0
    elif supply >= MAX_SUPPLY:
        supply_factor = 0.3
    else:
        supply_factor = 1.0 - 0.7 * ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))

    # Decide bid target.
    # If my hp is low, pay more to avoid death.
    # If my hp is high, still bid enough under pressure to avoid being outbid entirely.
    if my_hp <= 2.0:
        base = DAILY_SALARY * 0.95
    elif my_hp <= 4.0:
        base = DAILY_SALARY * (0.75 + 0.1 * pressure)
    else:
        base = DAILY_SALARY * (0.55 + 0.25 * pressure)

    target = base * (0.6 + 0.4 * supply_factor)

    # Additional adjustment: if highest_prev_bid was high, try to slightly exceed it.
    # But cap to not bankrupt.
    if highest_prev_bid > 0.0:
        target = max(target, highest_prev_bid * (0.92 + 0.08 * pressure))

    # Final clamp
    bid = min(my_budget, target)
    if bid < 0.0:
        bid = 0.0
    return float(bid)
